package net.civeira.phylax.feature.observe.observedissuecomment.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueComment;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.valueobject.AuthorVO;

@RequiredArgsConstructor
public class AuthorValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<AuthorVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param author
   * @return
   */
  public T author(AuthorVO author) {
    this.value = Optional.of(author);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param author
   * @return
   */
  public T author(Optional<AuthorVO> author) {
    this.value = author;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param author
   * @return
   */
  public T author(String author) {
    this.value = Optional.of(AuthorVO.from(author));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getAuthor() {
    return value.map(AuthorVO::getAuthor);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<AuthorVO> getAuthorValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public AuthorVO readAuthor(final Optional<ObservedIssueComment> original,
      final ConstraintFailList fails) {
    AuthorVO result = value.orElse(original.map(ObservedIssueComment::getAuthorValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "author", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetAuthor() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetAuthorIfMatches(final String field) {
    if ("author".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
